"""Native HTTP/1 framing-header semantics, following the original Hyper parser."""
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_mcp_service import document
LITERALS = ('transfer-encoding','content-length','connection','expect','upgrade','chunked','close','keep-alive','100-continue','connect')
SOURCE = '\ndef framing(s:readbuf, o:mutbuf, w:mutbuf) -> u32:\n    if length(s) < 192 or length(o) < 64 or length(w) < 4096:\n        return 4294967293\n    if word_load(s, 0) != 3544404736985876808:\n        return 4294967293\n    head = word_load(s, 8)\n    descriptor_size = word_load(s, 16)\n    if head > 417792 or descriptor_size < 128 or descriptor_size > 3328:\n        return 4294967293\n    if length(s) != 64 + head + descriptor_size:\n        return 4294967293\n    desc = 64 + head\n    if word_load(s, desc) != 3544423377143941448 or word_load(s, desc + 8) != head:\n        return 4294967293\n    count = word_load(s, desc + 56)\n    minor = word_load(s, desc + 48)\n    if count > 100 or descriptor_size != 128 + count * 32 or minor > 1:\n        return 4294967293\n    method_at = word_load(s, desc + 16)\n    method_size = word_load(s, desc + 24)\n    if method_at > head or method_size > head - method_at:\n        return 4294967293\n    wants_upgrade = equal(s, 64 + method_at, method_size, 9)\n    fill_range(w, 0, 128, 0)\n    word_store(w, 0, head)\n    word_store(w, 8, minor)\n    word_store(w, 16, choose(wants_upgrade, 1, 0))\n    word_store(w, 24, minor)\n    word_store(w, 72, count)\n    word_store(w, 80, desc)\n    index = 0\n    while index < word_load(w, 72):\n        result = header(s, w, word_load(w, 80) + 128 + index * 32)\n        if result != 1:\n            return result\n        index = index + 1\n    if word_load(w, 48) == 1 and word_load(w, 56) == 0:\n        return 0\n    if word_load(w, 48) == 1 and word_load(w, 112) == 1:\n        word_store(w, 24, 0)\n    mode = 0\n    if word_load(w, 48) == 1:\n        mode = 2\n        word_store(w, 64, 0)\n    elif word_load(w, 40) == 1 and word_load(w, 64) != 0:\n        mode = 1\n    word_store(o, 0, 3544410157234604360)\n    word_store(o, 8, mode)\n    word_store(o, 16, word_load(w, 64))\n    word_store(o, 24, word_load(w, 24))\n    word_store(o, 32, word_load(w, 32))\n    word_store(o, 40, word_load(w, 16))\n    word_store(o, 48, 0)\n    word_store(o, 56, 0)\n    return 64\n\ndef header(s:readbuf, w:mutbuf, row:u64) -> u64:\n    name_at = word_load(s, row)\n    name_size = word_load(s, row + 8)\n    value_at = word_load(s, row + 16)\n    value_size = word_load(s, row + 24)\n    head = word_load(w, 0)\n    if name_at > head or name_size > head - name_at or value_at > head or value_size > head - value_at:\n        return 4294967293\n    name_at = name_at + 64\n    value_at = value_at + 64\n    if equal(s, name_at, name_size, 0):\n        if word_load(w, 8) == 0:\n            return 0\n        word_store(w, 48, 1)\n        found = last_token(s, value_at, value_size, 5)\n        word_store(w, 56, choose(found, 1, 0))\n    elif equal(s, name_at, name_size, 1):\n        word_store(w, 112, 1)\n        if word_load(w, 48) == 0:\n            value = decimal(s, w, value_at, value_size)\n            if word_load(w, 120) != 0:\n                return 0\n            if value > 18446744073709551613:\n                return 2\n            if word_load(w, 40) == 1 and value != word_load(w, 64):\n                return 0\n            word_store(w, 40, 1)\n            word_store(w, 64, value)\n    elif equal(s, name_at, name_size, 2):\n        if word_load(w, 24) == 1:\n            closed = has_token(s, value_at, value_size, 6)\n            word_store(w, 24, choose(closed, 0, 1))\n        else:\n            alive = has_token(s, value_at, value_size, 7)\n            word_store(w, 24, choose(alive, 1, 0))\n    elif equal(s, name_at, name_size, 3):\n        expect = equal(s, value_at, value_size, 8)\n        word_store(w, 32, choose(expect, 1, 0))\n    elif equal(s, name_at, name_size, 4):\n        word_store(w, 16, word_load(w, 8))\n    return 1\n\ndef decimal(s:readbuf, w:mutbuf, start:u64, size:u64) -> u64:\n    word_store(w, 120, 0)\n    if size == 0:\n        word_store(w, 120, 1)\n        return 0\n    cursor = start\n    end = start + size\n    value = 0\n    while cursor < end:\n        ch = byte(s, cursor)\n        if ch < 48 or ch > 57:\n            word_store(w, 120, 1)\n            return 0\n        digit = ch - 48\n        if value > 1844674407370955161 or (value == 1844674407370955161 and digit > 5):\n            word_store(w, 120, 1)\n            return 0\n        value = value * 10 + digit\n        cursor = cursor + 1\n    return value\n\ndef has_token(s:readbuf, start:u64, size:u64, key:u64) -> bool:\n    if ascii(s, start, size) == False:\n        return False\n    end = start + size\n    cursor = start\n    while cursor <= end:\n        last = cursor\n        while last < end and byte(s, last) != 44:\n            last = last + 1\n        first = cursor\n        stop = last\n        while first < stop and (byte(s, first) == 32 or byte(s, first) == 9):\n            first = first + 1\n        while stop > first and (byte(s, stop - 1) == 32 or byte(s, stop - 1) == 9):\n            stop = stop - 1\n        if equal(s, first, stop - first, key):\n            return True\n        if last == end:\n            return False\n        cursor = last + 1\n    return False\n\ndef last_token(s:readbuf, start:u64, size:u64, key:u64) -> bool:\n    if ascii(s, start, size) == False:\n        return False\n    end = start + size\n    cursor = start\n    while cursor < end:\n        if byte(s, cursor) == 44:\n            start = cursor + 1\n        cursor = cursor + 1\n    while start < end and (byte(s, start) == 32 or byte(s, start) == 9):\n        start = start + 1\n    while end > start and (byte(s, end - 1) == 32 or byte(s, end - 1) == 9):\n        end = end - 1\n    return equal(s, start, end - start, key)\n\ndef ascii(s:readbuf, start:u64, size:u64) -> bool:\n    index = 0\n    while index < size:\n        ch = byte(s, start + index)\n        if (ch < 32 and ch != 9) or ch > 126:\n            return False\n        index = index + 1\n    return True\n\ndef lower(ch:u64) -> u64:\n    if ch >= 65 and ch <= 90:\n        return ch + 32\n    return ch\n'

def source():
    s=SOURCE
    s+='\ndef equal(s:readbuf, at:u64, size:u64, key:u64) -> bool:\n'
    for bank,first in enumerate(range(0,len(LITERALS),3)):
        s+=f'    if key < {min(first+3,len(LITERALS))}:\n        return equal_{bank}(s, at, size, key)\n'
    s+='    return False\n'
    for bank,first in enumerate(range(0,len(LITERALS),3)):
        s+=f'\ndef equal_{bank}(s:readbuf, at:u64, size:u64, key:u64) -> bool:\n'
        for index in range(first,min(first+3,len(LITERALS))):
            raw=LITERALS[index].encode()
            s+=f'    if key == {index}:\n        if size != {len(raw)}:\n            return False\n'
            for i,ch in enumerate(raw):
                s+=f'        if lower(byte(s, at + {i})) != {ch}:\n            return False\n'
            s+='        return True\n'
        s+='    return False\n'
    return s

def render():
    return render_assembly(document(source(),'mcp_http_framing'))

if __name__=='__main__':
    p=Path(__file__).resolve().parents[1]/'examples/hia_bootstrap/mcp_http_framing.hepta'
    raw=render();p.write_text(raw);print(p.name,len(raw.encode()))
